#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
"""Compare FISH task sets (extract_fish_tasks.py JSON) of several sessions of the same workload — repetitions, or the
tracing tiers min / default / max ("does the derived model change with the tracing dose?").

  python3 compare_tasksets.py label1=tasks1.json label2=tasks2.json [...]   (first = reference)

Structure: number of data tasks, multi-vertex tasks, vertices, trigger edges, sampled dependencies; set differences of
vertices (by node / entity name) and edges (by source name → target name, topic) against the reference.
Labels: per matched vertex the ratio of C p50 / C max to the reference; per matched edge δ p50, dispatch p50 and the
provenance (measured / inferred). Prints medians and the worst cases."""
import json, sys, collections
import numpy as np


def load(path):
    d = json.load(open(path))
    V = {}; E = {}
    for t in d['tasks']:
        for v in t['vertices']:
            V[v['name']] = dict(v, task=t['id'], infra=t['infra'])
    name = {v['id']: k for k, v in V.items()}
    for t in d['tasks']:
        for e in t['edges']:
            if e['kind'] in ('dds', 'intra') and e.get('n_pairs'):
                E[(name.get(e['u'], str(e['u'])), name.get(e['v'], str(e['v'])), e['topic'])] = e
    data = [t for t in d['tasks'] if not t['infra']]
    return dict(d=d, V=V, E=E, data=data)


def main():
    sets = [(a.split('=', 1)[0], load(a.split('=', 1)[1])) for a in sys.argv[1:]]
    if len(sets) < 2:
        sys.exit(__doc__)
    ref_l, ref = sets[0]
    print(f"{'session':<14}{'window s':>9}{'data tasks':>11}{'multi-v':>8}{'vertices':>9}{'data vert':>10}{'trig edges':>11}{'sampled':>8}{'measured δ':>11}{'inferred δ':>11}")
    for l, s in sets:
        w = s['d']['window']; pv = collections.Counter((e.get('prov') or '').split(':')[0] for e in s['E'].values() if e['kind'] == 'dds')
        print(f"{l:<14}{(w['t_end'] - w['t_ss']) / 1e9:>9.1f}{len(s['data']):>11}{sum(1 for t in s['data'] if t['size'] > 1):>8}{len(s['V']):>9}"
              f"{sum(1 for v in s['V'].values() if not v['infra']):>10}{len(s['E']):>11}{len(s['d']['sampled']):>8}{pv.get('measured', 0):>11}{pv.get('inferred', 0):>11}")
    q = lambda a, p: float(np.percentile(a, p)) if len(a) else float('nan')
    for l, s in sets[1:]:
        dv = {k for k, v in s['V'].items() if not v['infra']}; rv = {k for k, v in ref['V'].items() if not v['infra']}
        print(f"\n{l} vs {ref_l}: data vertices only in {ref_l}: {len(rv - dv)}, only in {l}: {len(dv - rv)}; "
              f"edges only in {ref_l}: {len(set(ref['E']) - set(s['E']))}, only in {l}: {len(set(s['E']) - set(ref['E']))}")
        for k in sorted(rv - dv)[:6]: print(f"    - {k[-110:]}")
        for k in sorted(dv - rv)[:6]: print(f"    + {k[-110:]}")
        rc50, rcmax, big = [], [], []
        for k in rv & dv:
            a, b = ref['V'][k].get('C') or {}, s['V'][k].get('C') or {}
            if a.get('p50') and b.get('p50') and a['p50'] > 50_000:        # ≥ 50 µs, below that the ratio is noise
                r = b['p50'] / a['p50']; rc50.append(r); rcmax.append(b['max'] / max(1, a['max'])); big.append((abs(np.log(r)), r, k, a['p50'], b['p50']))
        print(f"  C p50 ratio over {len(rc50)} vertices (C ≥ 50 µs): median {q(rc50, 50):.3f}, p10 {q(rc50, 10):.3f}, p90 {q(rc50, 90):.3f}; C max ratio median {q(rcmax, 50):.3f}")
        for _, r, k, a, b in sorted(big, reverse=True)[:5]:
            print(f"    x{r:.2f}  {a / 1e6:8.3f} → {b / 1e6:8.3f} ms  {k[-95:]}")
        dd, dp = [], []
        for k in set(ref['E']) & set(s['E']):
            a, b = ref['E'][k], s['E'][k]
            if (a.get('delta') or {}).get('p50') is not None and (b.get('delta') or {}).get('p50') is not None and a['kind'] == 'dds':
                dd.append((b['delta']['p50'] - a['delta']['p50']) / 1e6)
            if (a.get('dispatch') or {}).get('p50') is not None and (b.get('dispatch') or {}).get('p50') is not None:
                dp.append((b['dispatch']['p50'] - a['dispatch']['p50']) / 1e6)
        if dd: print(f"  δ p50 difference on {len(dd)} dds edges: median {q(dd, 50):+.3f} ms, p10 {q(dd, 10):+.3f}, p90 {q(dd, 90):+.3f}")
        if dp: print(f"  dispatch p50 difference on {len(dp)} edges: median {q(dp, 50):+.3f} ms, p90 {q(dp, 90):+.3f}")


if __name__ == '__main__':
    main()
